package extras

import "strings"

// UniqueTrimmed keeps one entry per spelling, ignoring case and surrounding blanks.
func UniqueTrimmed(entries []string) []string {
	known := make(map[string]bool, len(entries))
	result := make([]string, 0, len(entries))
	for _, entry := range entries {
		norm := strings.ToLower(strings.TrimSpace(entry))
		if norm != "" && !known[norm] {
			known[norm] = true
			result = append(result, entry)
		}
	}
	return result
}

package extras

// Batches cuts numbers into runs that are at most width long.
func Batches(numbers []int, width int) [][]int {
	if width <= 0 {
		return nil
	}
	batches := make([][]int, 0, (len(numbers)+width-1)/width)
	for from := 0; from < len(numbers); from += width {
		to := min(from+width, len(numbers))
		batches = append(batches, numbers[from:to])
	}
	return batches
}

