import "time"

// WholeDaysApart is the number of midnights between two moments.
func WholeDaysApart(a, b time.Time) int {
	if b.Before(a) {
		a, b = b, a
	}
	first := time.Date(a.Year(), a.Month(), a.Day(), 0, 0, 0, 0, time.UTC)
	last := time.Date(b.Year(), b.Month(), b.Day(), 0, 0, 0, 0, time.UTC)
	days := 0
	for cursor := first; cursor.Before(last); {
		cursor = cursor.AddDate(0, 0, 1)
		days++
	}
	return days
}

