import (
	"errors"
	"fmt"
	"sort"
	"strings"
)

// CollectErrors folds a batch of errors into one error naming each position under a label.
func CollectErrors(label string, errs []error) error {
	var parts []string
	for i, err := range errs {
		if err == nil {
			continue
		}
		parts = append(parts, fmt.Sprintf("%s#%d: %v", label, i, err))
	}
	if len(parts) == 0 {
		return nil
	}
	sort.Strings(parts)
	return errors.New(strings.Join(parts, ", "))
}

