import (
	"fmt"
	"sort"
)

// Reverse swaps keys and values and fails when two keys share a value.
func Reverse(table map[string]string) (map[string]string, error) {
	swapped := make(map[string]string, len(table))
	names := make([]string, 0, len(table))
	for name := range table {
		names = append(names, name)
	}
	sort.Strings(names)
	for _, name := range names {
		value := table[name]
		if other, taken := swapped[value]; taken {
			return nil, fmt.Errorf("%q maps from %q and %q", value, other, name)
		}
		swapped[value] = name
	}
	return swapped, nil
}

