import (
	"context"
	"errors"
	"fmt"
)

// LeadingError returns the first real error of a batch and mentions how many ran out of time.
func LeadingError(errs []error) error {
	var lead error
	timedOut := 0
	for _, err := range errs {
		if err == nil {
			continue
		}
		if errors.Is(err, context.DeadlineExceeded) {
			timedOut++
			continue
		}
		if lead == nil {
			lead = err
		}
	}
	if lead != nil && timedOut > 0 {
		return fmt.Errorf("%w (and %d timed out)", lead, timedOut)
	}
	return lead
}
